import React from "react";
import _ from "lodash";

import "../assets/css/loading-page.css";

function LoadingPage(props) {
  let radius = 150;

  let width = 30;
  let height = 30;

  let numPoints = 1;

  let x = window.outerWidth / 2 - radius - width / 2;
  let y = window.outerHeight / 2 - height / 2;

  return (
    <div className="loading-page-wrapper">
      <h1 className="loading-text-wrapper montserrat-light">loading</h1>
      {_.times(numPoints, n => {
        const angle = (n * (2 * Math.PI)) / numPoints;

        const firstArcX = 2 * radius * Math.cos(angle);
        const firstArcY = 2 * radius * Math.sin(angle);
        const secondArcX = 2 * radius * Math.cos(angle + Math.PI);
        const secondArcY = 2 * radius * Math.sin(angle + Math.PI);

        return (
          <div
            className="circle"
            style={{
              offsetPath: `path("M ${x},${y} a ${radius},${radius} 0 1,0 ${firstArcX},${firstArcY} a ${radius},${radius} 0 1,0 ${secondArcX},${secondArcY}")`
            }}
          ></div>
        );
      })}
    </div>
  );
}

export default LoadingPage;
